// Runnable demo modelling topic/partition/offset in memory.
package com.bank.topicmodel.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TopicModelDemo {
    private static final Logger log = Logger.getLogger(TopicModelDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Topic transfers = new Topic("transfers", 3); // 3 partitions

        // Produce several transfers; key = account id keeps ordering per account
        transfers.produce("SAV2001", new TransferRecord("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000")));
        transfers.produce("SAV2001", new TransferRecord("TXF-2", "SAV2001", "CUR3001", new BigDecimal("12000")));
        transfers.produce("CUR3001", new TransferRecord("TXF-3", "CUR3001", "SAV2001", new BigDecimal("8000")));
        transfers.produce("SAV2001", new TransferRecord("TXF-4", "SAV2001", "CUR3001", new BigDecimal("3000")));

        // Consume Rajesh's partition from the beginning
        int rajeshPartition = transfers.partitionFor("SAV2001");
        TransferConsumer consumer = new TransferConsumer(transfers, rajeshPartition);
        log.info(() -> "Consuming partition " + rajeshPartition + " from offset 0");
        consumer.consumeFrom(0);

        // Fraud team replays from offset 1 after a model update
        log.info(() -> "Replaying partition " + rajeshPartition + " from offset 1");
        consumer.consumeFrom(1);
    }
}

