class TransferRecord {
    private final String transferId, fromAccount, toAccount;
    private final BigDecimal amount;
    TransferRecord(String transferId, String fromAccount, String toAccount, BigDecimal amount) {
        this.transferId = transferId; this.fromAccount = fromAccount;
        this.toAccount = toAccount; this.amount = amount;
    }
    String getTransferId() { return transferId; }
    String getFromAccount() { return fromAccount; }
    BigDecimal getAmount() { return amount; }
    @Override public String toString() {
        return transferId + " " + fromAccount + "->" + toAccount + " " + amount;
    }
}

// ─── Would be in Partition.java ───
class Partition {
    private final int id;
    private final List<TransferRecord> log = new ArrayList<>(); // append-only, index = offset
    Partition(int id) { this.id = id; }
    int append(TransferRecord r) { log.add(r); return log.size() - 1; } // returns the offset
    TransferRecord at(long offset) { return log.get((int) offset); }
    long endOffset() { return log.size(); }
    int getId() { return id; }
}

// ─── Would be in Topic.java ───
class Topic {
    private static final Logger log = Logger.getLogger(Topic.class.getName());
    private final String name;
    private final List<Partition> partitions = new ArrayList<>();
    Topic(String name, int partitionCount) {
        this.name = name;
        for (int i = 0; i < partitionCount; i++) partitions.add(new Partition(i));
    }
    // Hash the key to pick a partition: same key -> same partition -> ordered
    int partitionFor(String key) {
        return Math.floorMod(key.hashCode(), partitions.size());
    }
    void produce(String key, TransferRecord r) {
        int p = partitionFor(key);
        long offset = partitions.get(p).append(r);
        log.info(() -> "PRODUCE topic=" + name + " key=" + key
                + " -> partition=" + p + " offset=" + offset + " [" + r + "]");
    }
    Partition partition(int id) { return partitions.get(id); }
}

// ─── Would be in TransferConsumer.java ───
class TransferConsumer {
    private static final Logger log = Logger.getLogger(TransferConsumer.class.getName());
    private final Topic topic;
    private final int partitionId;
    TransferConsumer(Topic topic, int partitionId) {
        this.topic = topic; this.partitionId = partitionId;
    }
    void consumeFrom(long startOffset) {
        Partition p = topic.partition(partitionId);
        for (long off = startOffset; off < p.endOffset(); off++) {
            long finalOff = off;
            log.info(() -> "CONSUME partition=" + partitionId + " offset=" + finalOff
                    + " record=" + p.at(finalOff));
        }
    }
}

